public FieldMatrix<T> outerProduct(ArrayFieldVector<T> v) {
    final int m = getDimension();
    final int n = v.getDimension();
    final FieldMatrix<T> product = new Array2DRowFieldMatrix<T>(field, m, n);
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            product.setEntry(i, j, data[i].multiply(v.data[j]));
        }
    }
    return product;
}

